<script setup lang="ts">
import { computed,nextTick,onBeforeUnmount,onMounted,ref,watch } from 'vue';
import type { MusicAlbumSummary,MusicQueueMode,MusicSource,MusicTrack,PlaybackSessionSnapshot,PlayerLoadStatus,PlayerStats } from '@free-new-desk/contracts';
import MusicNetworkSourceDialog from '../components/MusicNetworkSourceDialog.vue';

import { musicTrackPosition,musicTrackDuration,musicFilePosition,musicLyricPosition,parseLrc,activeLyricIndex,type LrcLine } from '@free-new-desk/contracts';
import { clockStats as stats,clockRuntime as runtime,clockLoadStatus as loadStatus,clockPosition,clockStale,clockDiagnostics,startPlaybackClock,refreshPlaybackClock,seekPlayback } from '../stores/playback-clock.js';
import MusicArtwork from '../components/MusicArtwork.vue';
import {adjacentMusicId} from '../stores/music-playback.js';
import MusicIcon from '../components/MusicIcon.vue';
const lyricTimeBase=ref<'track'|'file'>('track');
const musicPosition=computed(()=>runtime.value.domain==='music'?musicTrackPosition(clockPosition.value,current.value):0);
const musicDuration=computed(()=>musicTrackDuration(runtime.value.domain==='music'?stats.value?.duration??current.value?.duration??0:current.value?.duration??0,current.value));
const lyricsElement=ref<HTMLElement|null>(null),manualFollowUntil=ref(0),lyricOffset=ref(0),queueCollapsed=ref(true);
const showSources=ref(false);
const section=ref<'library'|'playing'>('library'),selectedAlbum=ref(''),selectedArtist=ref('');
const queueButton=ref<HTMLButtonElement|null>(null);
function albumKey(t:MusicTrack){return t.albumId||JSON.stringify(['legacy',t.sourceId,t.album,t.artist]);}
function closeQueue(){queueCollapsed.value=true;void nextTick(()=>queueButton.value?.focus());}
async function pauseScan(source:MusicSource){await window.desktop.music.pauseScan(source.id);await loadSources();}
let sourceTimer:ReturnType<typeof setInterval>|undefined,followTimer:ReturnType<typeof setTimeout>|undefined,resizeObserver:ResizeObserver|undefined;
let seekTarget:{loadId:string;requestId:string}|undefined,polling=false;
function beginSeek(){if(!runtime.value.loadId)return;seeking.value=true;seekTarget={loadId:runtime.value.loadId,requestId:runtime.value.requestId};}
function cancelSeek(){seeking.value=false;seekTarget=undefined;}
function previewSeek(){if(!seekTarget)beginSeek();}
function manualLyrics(){manualFollowUntil.value=Date.now()+4000;if(followTimer)clearTimeout(followTimer);followTimer=setTimeout(resumeFollow,4100);}
function followLyrics(){const box=lyricsElement.value,item=box?.querySelector<HTMLElement>('.active');if(!box||!item||manualFollowUntil.value>Date.now())return;box.scrollTo({top:Math.max(0,Math.min(box.scrollHeight-box.clientHeight,box.scrollTop+item.getBoundingClientRect().top-box.getBoundingClientRect().top-box.clientTop-(box.clientHeight-item.clientHeight)/2)),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function resumeFollow(){manualFollowUntil.value=0;followLyrics();}
function adjustLyrics(delta:number){lyricOffset.value+=delta;if(current.value)localStorage.setItem('music.lyricOffset.'+current.value.id,String(lyricOffset.value));}
function removeQueue(id:string){queueIds.value=queueIds.value.filter(v=>v!==id);persistQueue();}
function moveQueue(id:string,delta:number){const i=queueIds.value.indexOf(id),j=i+delta;if(i<0||j<0||j>=queueIds.value.length)return;const next=[...queueIds.value];[next[i],next[j]]=[next[j]!,next[i]!];queueIds.value=next;persistQueue();}
async function chooseCurrentArtwork(){if(current.value){const result=await window.desktop.music.chooseArtwork({trackId:current.value.id});if(result)artwork.value=result;}}

const TRACK_ROW_HEIGHT=48,VIRTUAL_OVERSCAN=8,VIRTUAL_WINDOW=48;
const sources=ref<MusicSource[]>([]);const tracks=ref<MusicTrack[]>([]);const libraryTracks=ref<MusicTrack[]>([]);const sourceId=ref('');const query=ref('');const tab=ref<'tracks'|'albums'|'artists'>('tracks');const onlyFavorites=ref(false);const loading=ref(false);const status=ref('');const current=ref<MusicTrack|null>(null);const artwork=ref('');const lyrics=ref<LrcLine[]>([]);const rawLyrics=ref('');const lyricsKind=ref<'synced'|'plain'|'instrumental'|'not-found'>('not-found');const lyricsProvider=ref('');const queueIds=ref<string[]>([]);const mode=ref<MusicQueueMode>((localStorage.getItem('music.mode') as MusicQueueMode)||'sequence');const volume=ref(Number(localStorage.getItem('music.volume')??80));const seeking=ref(false);const seekValue=ref(0);const trackScrollTop=ref(0);const trackList=ref<HTMLElement|null>(null);const networkSourceOpen=ref(false);let wasScanning=false;let timer:ReturnType<typeof setInterval>|undefined;let searchTimer:ReturnType<typeof setTimeout>|undefined;let removeRuntime:(()=>void)|undefined;let assetGeneration=0;let searchGeneration=0;let playGeneration=0;let lastProgressSavedAt=0;
const albumRows=ref<MusicAlbumSummary[]>([]),artistRows=ref<string[]>([]),totalTracks=ref(0),totalAlbums=ref(0),nextPage=ref('');
const sourceMap=computed(()=>new Map(sources.value.map(item=>[item.id,item])));const trackMap=computed(()=>new Map(libraryTracks.value.map(item=>[item.id,item])));const queue=computed(()=>queueIds.value.map(id=>trackMap.value.get(id)).filter((item):item is MusicTrack=>Boolean(item)));const filtered=computed(()=>tracks.value); const virtualStart=computed(()=>Math.max(0,Math.floor(trackScrollTop.value/TRACK_ROW_HEIGHT)-VIRTUAL_OVERSCAN));const visibleTracks=computed(()=>filtered.value.slice(virtualStart.value,virtualStart.value+VIRTUAL_WINDOW));const virtualTop=computed(()=>virtualStart.value*TRACK_ROW_HEIGHT);const virtualBottom=computed(()=>Math.max(0,(filtered.value.length-virtualStart.value-visibleTracks.value.length)*TRACK_ROW_HEIGHT));const artists=computed(()=>artistRows.value);const albums=computed(()=>albumRows.value);const currentIndex=computed(()=>current.value?queue.value.findIndex(item=>item.id===current.value?.id):-1);const activeLyric=computed(()=>runtime.value.domain==='music'&&runtime.value.trackId===current.value?.id?activeLyricIndex(lyrics.value,musicLyricPosition(clockPosition.value,current.value,lyricTimeBase.value,lyricOffset.value)):-1);const nowFormat=computed(()=>current.value?.cueTrack?`CUE #${String(current.value.cueTrack).padStart(2,'0')} · ${current.value.format}`:current.value?.format||'—');const nowSource=computed(()=>current.value?sourceMap.value.get(current.value.sourceId)?.name??'':'');const lyricStatus=computed(()=>lyricsKind.value==='synced'?'逐行同步'+(lyricsProvider.value?' · '+lyricsProvider.value:''):lyricsKind.value==='plain'?'普通文本'+(lyricsProvider.value?' · '+lyricsProvider.value:''):lyricsKind.value==='instrumental'?'纯音乐 / 器乐曲':'暂无歌词');
function formatTime(value:number|undefined){const total=Math.max(0,Math.floor(value??0));return `${Math.floor(total/60).toString().padStart(2,'0')}:${(total%60).toString().padStart(2,'0')}`;}

function persistQueue(){localStorage.setItem('music.queue',JSON.stringify(queueIds.value.slice(0,2000)));}
function restoreQueue(){try{const parsed=JSON.parse(localStorage.getItem('music.queue')??'[]') as unknown;if(Array.isArray(parsed))queueIds.value=parsed.filter((item):item is string=>typeof item==='string').slice(0,2000);}catch{queueIds.value=[];}}
function readProgress():Record<string,number>{try{const parsed=JSON.parse(localStorage.getItem('music.progress')??'{}') as unknown;if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))return parsed as Record<string,number>;}catch{/* ignore damaged local state */}return{};}
function saveProgress(trackId:string,position:number,duration?:number){const all=readProgress();if(!Number.isFinite(position)||position<3||(duration&&duration-position<10))delete all[trackId];else all[trackId]=Math.round(position*10)/10;const bounded=Object.fromEntries(Object.entries(all).slice(-500));localStorage.setItem('music.progress',JSON.stringify(bounded));}
function resetTrackScroll(){trackScrollTop.value=0;if(trackList.value)trackList.value.scrollTop=0;}
function onTrackScroll(event:Event){trackScrollTop.value=(event.currentTarget as HTMLElement).scrollTop;}
async function loadSources(){sources.value=await window.desktop.music.listSources();if(sourceId.value&&!sources.value.some(item=>item.id===sourceId.value))sourceId.value='';}
function catalogQuery(after=''){return{...(sourceId.value?{sourceId:sourceId.value}:{}),...(query.value.trim()?{query:query.value.trim()}:{}),...(selectedAlbum.value?{albumId:selectedAlbum.value}:{}),...(selectedArtist.value?{artist:selectedArtist.value==='未知艺人'?'':selectedArtist.value}:{}),favorite:onlyFavorites.value,after};}
async function loadTracks(append=false){const generation=++searchGeneration;loading.value=true;try{const result=await window.desktop.music.catalog(catalogQuery(append?nextPage.value:''));if(generation!==searchGeneration)return;tracks.value=append?[...tracks.value,...result.tracks]:result.tracks;albumRows.value=result.albums;artistRows.value=result.artists.map(a=>a||'未知艺人');totalTracks.value=result.total;totalAlbums.value=result.albumCount;nextPage.value=result.next;if(!append)resetTrackScroll();const trackIds=new Set(tracks.value.map(t=>t.id)),albumIds=new Set(result.albums.map(a=>a.track.id)),queuedIds=new Set(queueIds.value);const map=new Map(libraryTracks.value.map(t=>[t.id,t]));for(const track of result.tracks)map.set(track.id,track);for(const album of result.albums)map.set(album.track.id,album.track);libraryTracks.value=[...map.values()].filter(t=>queuedIds.has(t.id)||trackIds.has(t.id)||t.id===current.value?.id||albumIds.has(t.id));}catch(error){status.value=error instanceof Error?error.message:String(error);}finally{if(generation===searchGeneration)loading.value=false;}}
let refreshing=false;
async function refreshLibrary(){if(refreshing)return;refreshing=true;try{await loadSources();await loadTracks();const ids=[...new Set([...queueIds.value,localStorage.getItem('music.currentTrack')??''])].filter(id=>id&&!libraryTracks.value.some(t=>t.id===id));for(let i=0;i<ids.length;i+=20){const result=await Promise.all(ids.slice(i,i+20).map(id=>window.desktop.music.getTrack(id)));libraryTracks.value.push(...result.filter((t):t is MusicTrack=>Boolean(t)));}}finally{refreshing=false;}}
async function addLocalSource(){loading.value=true;try{const result=await window.desktop.music.addLocalSource();if(!result.canceled){status.value='已添加来源，正在后台扫描';await refreshLibrary();if(result.source)sourceId.value=result.source.id;}}catch(error){status.value=error instanceof Error?error.message:String(error);}finally{loading.value=false;}}
async function onNetworkSourceSaved(source:MusicSource,count:number){networkSourceOpen.value=false;status.value=`已添加「${source.name}」，正在后台扫描`;sourceId.value=source.id;onlyFavorites.value=false;await refreshLibrary();sourceId.value=source.id;await loadTracks();}
async function rescan(source:MusicSource){loading.value=true;source.scanState='scanning';try{const result=await window.desktop.music.scan(source.id);status.value=result.canceled?`${source.name}：扫描已取消，保留上次完整结果`:`${source.name}：已加入后台扫描`;await refreshLibrary();}catch(error){status.value=error instanceof Error?error.message:String(error);await loadSources();}finally{loading.value=false;}}
async function cancelScan(source:MusicSource){if(await window.desktop.music.cancelScan(source.id))status.value=`正在取消 ${source.name} 的扫描…`;}
async function removeSource(source:MusicSource){if(!window.confirm(`删除音乐来源「${source.name}」？不会删除磁盘或服务器上的音乐文件。`))return;await window.desktop.music.removeSource(source.id);if(sourceId.value===source.id)sourceId.value='';await refreshLibrary();}
function scheduleSearch(){if(searchTimer)clearTimeout(searchTimer);searchTimer=setTimeout(()=>{void loadTracks();},250);}
async function loadNowPlayingAssets(track:MusicTrack){const generation=++assetGeneration;lyricOffset.value=Number(localStorage.getItem('music.lyricOffset.'+track.id)??0);artwork.value='';rawLyrics.value='';lyrics.value=[];lyricsKind.value='not-found';lyricsProvider.value='';const applies=()=>generation===assetGeneration&&current.value?.id===track.id;await Promise.all([window.desktop.music.artwork(track.id).then(cover=>{if(applies())artwork.value=cover??'';}).catch(()=>undefined),window.desktop.music.lyricsInfo(track.id).then(info=>{if(applies()){lyricTimeBase.value=info.timeBase??'track';rawLyrics.value=info.text;lyrics.value=info.kind==='synced'?parseLrc(info.text):[];lyricsKind.value=info.kind;lyricsProvider.value=info.provider??'';}}).catch(()=>undefined)]);}
async function playTrack(track:MusicTrack,initiator:'user'|'auto-next'|'restore'='user'){const generation=++playGeneration;cancelSeek();assetGeneration++;artwork.value='';rawLyrics.value='';lyrics.value=[];lyricsKind.value='not-found';lyricsProvider.value='';try{if(!queueIds.value.includes(track.id)){queueIds.value.push(track.id);queueIds.value=queueIds.value.slice(-2000);persistQueue();}status.value=`正在播放：${track.title}`;const result=await window.desktop.music.play({trackId:track.id,initiator});if(generation!==playGeneration)return;if(!result.ok)throw new Error(result.detail??'音乐加载失败');current.value=result.track;localStorage.setItem('music.currentTrack',result.track.id);runtime.value=result.session;if(initiator==='restore'){const position=readProgress()[track.id];if(typeof position==='number'&&Number.isFinite(position)&&position>2&&(!track.duration||position<track.duration-10))await seekPlayback(position,result.session.loadId!,result.session.requestId);}void loadNowPlayingAssets(result.track);await nextTick();await poll();}catch(error){const message=error instanceof Error?error.message:String(error);if(generation===playGeneration&&!message.includes('PLAYBACK_SUPERSEDED'))status.value=message;}}
async function queueAll(){const all:MusicTrack[]=[];let after='';do{const page=await window.desktop.music.catalog(catalogQuery(after));all.push(...page.tracks);after=page.next;}while(after&&all.length<2000);queueIds.value=all.slice(0,2000).map(t=>t.id);libraryTracks.value=[...new Map([...libraryTracks.value,...all].map(t=>[t.id,t])).values()];persistQueue();status.value=`已加入 ${queueIds.value.length} 首到播放列表`;}
function clearQueue(){queueIds.value=[];persistQueue();status.value='播放队列已清空';}
async function toggleFavorite(track:MusicTrack){track.favorite=await window.desktop.music.toggleFavorite(track.id);if(current.value?.id===track.id)current.value.favorite=track.favorite;if(onlyFavorites.value)await loadTracks();}
async function playAdjacent(direction:1|-1,initiator:'user'|'auto-next'='user'){const id=adjacentMusicId(queueIds.value,current.value?.id,direction,mode.value,initiator==='auto-next');const track=id?trackMap.value.get(id):undefined;if(track)await playTrack(track,initiator);}
function setMode(next:MusicQueueMode){mode.value=next;localStorage.setItem('music.mode',next);}
function cycleMode(){setMode(mode.value==='sequence'?'repeat-one':mode.value==='repeat-one'?'shuffle':'sequence');}
function modeLabel(){return mode.value==='sequence'?'顺序播放':mode.value==='repeat-one'?'单曲循环':'随机播放';}
async function togglePause(){if(runtime.value.domain!=='music'){if(current.value)await playTrack(current.value,'restore');return;}await window.desktop.playback.control({command:'pause',value:!(stats.value?.paused??false)});await poll();}
async function toggleMute(){await window.desktop.playback.control({command:'mute',value:!(stats.value?.muted??false)});await poll();}
async function persistVolume(){const safe=Math.max(0,Math.min(100,Math.round(volume.value)));volume.value=safe;localStorage.setItem('music.volume',String(safe));await window.desktop.playback.control({command:'volume',value:safe});}
async function seek(){const target=seekTarget;if(!target)return;seekTarget=undefined;seeking.value=false;try{await seekPlayback(musicFilePosition(seekValue.value,current.value),target.loadId,target.requestId);}catch(error){status.value=error instanceof Error?error.message:String(error);}}

async function poll(){if(polling)return;polling=true;try{await refreshPlaybackClock();const s=stats.value,l=loadStatus.value,r=runtime.value;if(r.domain!=='music')return;
if(r.trackId&&r.trackId!==current.value?.id){const track=trackMap.value.get(r.trackId);if(track){current.value=track;void loadNowPlayingAssets(track);}}
if(s&&current.value&&Date.now()-lastProgressSavedAt>=5000){saveProgress(current.value.id,s.position,s.duration);lastProgressSavedAt=Date.now();void window.desktop.music.syncDiagnostics({activeIndex:activeLyric.value,offset:lyricOffset.value,stale:clockStale.value,timeBase:lyricTimeBase.value,...clockDiagnostics});}

}finally{polling=false;}}

function selectArtist(artist:string){selectedArtist.value=artist;selectedAlbum.value='';tab.value='tracks';}
function selectAlbum(album:string){selectedAlbum.value=album;selectedArtist.value='';tab.value='tracks';}
function keydown(event:KeyboardEvent){if(event.key==='Escape'&&showSources.value){showSources.value=false;return;}if(event.key==='Escape'&&!queueCollapsed.value){closeQueue();return;}const target=event.target as HTMLElement|null;if(target&&['INPUT','SELECT','TEXTAREA'].includes(target.tagName))return;if(event.code==='Space'&&runtime.value.domain==='music'){event.preventDefault();void togglePause();return;}if((event.key==='ArrowLeft'||event.key==='ArrowRight')&&runtime.value.domain==='music'&&runtime.value.loadId){event.preventDefault();const next=Math.max(0,clockPosition.value+(event.key==='ArrowLeft'?-10:10));void seekPlayback(next,runtime.value.loadId,runtime.value.requestId).catch(error=>{status.value=error instanceof Error?error.message:String(error);});}}
onMounted(async()=>{startPlaybackClock();restoreQueue();removeRuntime=window.desktop.playback.onRuntimeSessionChanged(value=>{runtime.value=value;if(value.domain!=='music'&&value.status==='playing')status.value=`当前播放器已切换到${value.domain==='live'?'直播':'点播'}模式`;});window.addEventListener('keydown',keydown);await refreshLibrary();const savedCurrent=localStorage.getItem('music.currentTrack');if(savedCurrent){const track=libraryTracks.value.find(item=>item.id===savedCurrent);if(track)current.value=track;}if(current.value)void loadNowPlayingAssets(current.value);sourceTimer=setInterval(()=>{void loadSources().then(()=>{if(sources.value.some(s=>s.scanState==='scanning')||wasScanning){wasScanning=sources.value.some(s=>s.scanState==='scanning');void refreshLibrary();}});},3000);timer=setInterval(()=>{void poll();},275);void poll();});
onBeforeUnmount(()=>{assetGeneration+=1;playGeneration+=1;searchGeneration+=1;if(timer)clearInterval(timer);if(sourceTimer)clearInterval(sourceTimer);if(followTimer)clearTimeout(followTimer);resizeObserver?.disconnect();if(searchTimer)clearTimeout(searchTimer);removeRuntime?.();window.removeEventListener('keydown',keydown);if(current.value){localStorage.setItem('music.currentTrack',current.value.id);if(runtime.value.domain==='music'&&stats.value)saveProgress(current.value.id,stats.value.position,stats.value.duration);}});
watch([selectedAlbum,selectedArtist,onlyFavorites],()=>{void loadTracks();});
watch(clockPosition,value=>{if(!seeking.value)seekValue.value=musicTrackPosition(value,current.value);});
watch([activeLyric,lyrics,section],()=>{void nextTick(followLyrics);});
watch(lyricsElement,element=>{resizeObserver?.disconnect();if(element){resizeObserver=new ResizeObserver(()=>followLyrics());resizeObserver.observe(element);}});
watch(()=>runtime.value.loadId,()=>{cancelSeek();assetGeneration++;artwork.value='';lyrics.value=[];rawLyrics.value='';lyricsKind.value='not-found';lyricsProvider.value='';const track=runtime.value.trackId?trackMap.value.get(runtime.value.trackId):undefined;if(track){current.value=track;void loadNowPlayingAssets(track);}});
</script>

<template>
  <section class="music-page" :class="{'now-view':section==='playing'}">
    <header class="music-heading"><div><h1>音乐</h1><nav class="view-tabs" aria-label="音乐视图"><button :class="{active:section==='library'}" @click="section='library'">音乐库</button><button :class="{active:section==='playing'}" @click="section='playing'">正在播放</button></nav></div><div class="music-actions"><button class="source-mobile-button" @click="showSources=!showSources">音乐来源</button><input v-model="query" data-search-input aria-label="搜索音乐" placeholder="搜索歌曲、专辑或歌手" @input="section='library';selectedAlbum='';selectedArtist='';scheduleSearch()"/><button @click="addLocalSource">添加文件夹</button><button class="accent-button" @click="networkSourceOpen=true">＋ 添加 NAS / WebDAV</button></div></header>
    <div class="music-body">
      <aside class="source-panel" :class="{open:showSources}" aria-label="音乐来源"><button v-if="showSources" @click="showSources=false">关闭来源面板</button><button class="all-sources" :class="{selected:!sourceId}" @click="sourceId='';loadTracks(false)">全部来源 <small>{{totalTracks}} 首</small></button><div v-for="source in sources" :key="source.id" class="source-card" :class="{selected:sourceId===source.id}"><button class="source-name" @click="sourceId=source.id;showSources=false;loadTracks(false)"><span class="source-dot" :class="source.scanState"/>{{source.name}}</button><small>{{source.kind==='smb'?'SMB · NAS':source.kind==='webdav'?'WebDAV':'本地音乐'}}</small><p v-if="source.scanJob">{{source.scanJob.state==='paused'?'已暂停':source.scanState==='scanning'?'后台扫描':source.scanJob.state==='interrupted'?'上次扫描中断':source.scanState==='error'?'扫描失败':'扫描记录'}} · 已处理 {{source.scanJob.processed}} 首</p><p v-if="source.message" class="source-message" :title="source.message">{{source.message}}</p><div class="source-tools"><template v-if="source.scanState==='scanning'"><button @click="pauseScan(source)">暂停</button><button @click="cancelScan(source)">取消</button></template><button v-else @click="rescan(source)">{{source.scanJob?.state==='paused'?'继续':'扫描'}}</button><button @click="removeSource(source)">移除</button></div></div><p v-if="!sources.length" class="empty-note">添加文件夹或 NAS，建立你的音乐库。</p></aside>
      <section v-if="section==='library'" class="library-panel">
        <nav class="library-tabs" aria-label="音乐分类"><button :class="{active:tab==='tracks'&&!onlyFavorites}" @click="tab='tracks';onlyFavorites=false;selectedAlbum='';selectedArtist=''">歌曲</button><button :class="{active:tab==='albums'}" @click="tab='albums';onlyFavorites=false;selectedAlbum='';selectedArtist=''">专辑</button><button :class="{active:tab==='artists'}" @click="tab='artists';onlyFavorites=false;selectedAlbum='';selectedArtist=''">歌手</button><button :class="{active:onlyFavorites}" @click="tab='tracks';onlyFavorites=true;selectedAlbum='';selectedArtist=''">收藏</button><span class="spacer"/><small>{{totalAlbums}} 张专辑 · {{totalTracks}} 首歌曲</small><button @click="queueAll">加入播放列表</button></nav>
        <div v-if="selectedAlbum||selectedArtist" class="filter-note"><span>正在查看{{selectedAlbum?'专辑':'歌手'}}中的歌曲</span><button @click="selectedAlbum='';selectedArtist=''">显示全部</button></div>
        <div v-if="tab==='albums'" class="entity-grid"><button v-for="album in albums" :key="album.key" class="album-card" @click="selectAlbum(album.key)"><span class="entity-art"><MusicArtwork :track-id="album.track.id"/></span><strong>{{album.title}}</strong><span>{{album.artist||'未知专辑歌手'}}</span><small>{{album.track.releaseDate||'年份未知'}} · {{album.count}} 首</small></button></div>
        <div v-else-if="tab==='artists'" class="entity-grid"><button v-for="artist in artists" :key="artist" class="album-card artist-card" @click="selectArtist(artist)"><span class="entity-art"><MusicArtwork :artist="artist"/></span><strong>{{artist}}</strong></button></div>
        <div v-else class="track-section"><div class="track-head"><span>#</span><span>歌曲</span><span>歌手</span><span>专辑</span><span>格式</span><span>时长</span><span/></div><div ref="trackList" class="track-list" @scroll="onTrackScroll"><div :style="{height:virtualTop+'px'}"/><div v-for="(track,index) in visibleTracks" :key="track.id" class="track-row" :class="{playing:current?.id===track.id}" @dblclick="playTrack(track)"><span>{{virtualStart+index+1}}</span><button class="track-title" @click="playTrack(track)">{{track.title}}</button><button @click="selectArtist(track.artist)">{{track.artist||'未知歌手'}}</button><button @click="selectAlbum(albumKey(track))">{{track.album||'未知专辑'}}</button><small>{{track.format}}</small><small>{{formatTime(track.duration)}}</small><button :aria-label="track.favorite?'取消收藏':'收藏歌曲'" :class="{favorite:track.favorite}" @click="toggleFavorite(track)"><MusicIcon name="heart"/></button></div><div :style="{height:virtualBottom+'px'}"/><button v-if="nextPage" class="load-more" :disabled="loading" @click="loadTracks(true)">加载更多歌曲</button><p v-if="!filtered.length" class="empty-note">{{loading?'正在读取音乐库…':'暂无匹配歌曲，添加来源或调整筛选。'}}</p></div></div>
      </section>
